insert into practice_context_blocks (id, exercise_id, label, image_url, text_content, block_type) values
  ('312cf323-d798-4754-b4d0-7aa30134553e', 'dab62abd-af81-4541-b98b-0f905c8c92dc', $$inleiding: tijdelijk importverbod op landbouwproducten$$,
   $$economie-vwo-2018-i-zakelijk-boeren-context1.png$$,
   $$Een land importeert een groot deel van het benodigde voedsel. Een econome meent dat in dit land de productiekosten van voedsel relatief hoog zijn doordat de voedselproductie minder kapitaalintensief is dan in andere landen. Dit kan volgens haar veranderen als voor de voornaamste landbouwproducten tijdelijk een importverbod wordt ingesteld. Dat gaat weliswaar tijdelijk ten koste van de welvaart van de consumenten, maar geeft binnenlandse producenten de gelegenheid om in de periode waarin het importverbod van kracht is, hun productie efficiënter te maken. De econome hanteert het onderstaande model voor de binnenlandse vraag en het binnenlands aanbod op de markt voor één van de betreffende landbouwproducten. De valuta van het land is de UR.$$, 'inline'),
  ('ecf140c3-48b1-4867-a107-f33dd4056e5a', 'dab62abd-af81-4541-b98b-0f905c8c92dc', $$model binnenlandse vraag en aanbod (Qᵥ, Qₐ) met legenda$$,
   $$economie-vwo-2018-i-zakelijk-boeren-context2.png$$,
   $$Qᵥ = −2P + 100
Qₐ = 4P − 80
Qₐ = Qᵥ
P = prijs per ton in UR
Qᵥ = binnenlandse vraag in duizenden tonnen
Qₐ = binnenlands aanbod in duizenden tonnen$$, 'inline'),
  ('7a23cae2-3f29-41f5-9159-f96eceaca203', 'dab62abd-af81-4541-b98b-0f905c8c92dc', $$marktsituatie met import bij wereldmarktprijs 25 UR$$,
   $$economie-vwo-2018-i-zakelijk-boeren-context3.png$$,
   $$De situatie op de betreffende markt met import bij een prijs op de wereldmarkt van 25 UR per ton is in figuur 1 weergegeven.$$, 'inline'),
  ('d2a1ba47-3b9a-43f9-acf2-e2f9dc2eae74', 'dab62abd-af81-4541-b98b-0f905c8c92dc', $$figuur 1: marktsituatie voor het geselecteerde landbouwproduct$$,
   $$economie-vwo-2018-i-zakelijk-boeren-context4.png$$,
   $$Figuur 1 marktsituatie voor het geselecteerde landbouwproduct
Grafiek met prijs tegen hoeveelheid: dalende lijn ''binnenlandse vraag'', stijgende lijn ''binnenlands aanbod'' en horizontale lijn ''wereldmarktprijs'' bij 25 UR. Vlakken A, B, C, D, E, F, G en H tussen de lijnen.$$, 'inline'),
  ('b9a10ae9-93db-41f6-92ee-718579f6f341', 'dab62abd-af81-4541-b98b-0f905c8c92dc', $$Consumentenbond: importquotum met maximaal 10% prijsstijging$$,
   $$economie-vwo-2018-i-zakelijk-boeren-context5.png$$,
   $$Een compleet importverbod op de voornaamste landbouwproducten zou volgens een woordvoerster van de Consumentenbond de voedselprijzen teveel doen stijgen. De Consumentenbond adviseert de regering om de import van dit specifieke product gedeeltelijk te beperken tot een maximaal toegestane hoeveelheid waarbij de prijsstijging slechts 10% bedraagt.$$, 'inline'),
  ('a684ec44-57ef-4198-9d95-f2addf640b60', 'dab62abd-af81-4541-b98b-0f905c8c92dc', $$importverbod kan gemiddelde variabele kosten verlagen$$,
   $$economie-vwo-2018-i-zakelijk-boeren-context6.png$$,
   $$De econome meent dat voor de binnenlandse voedselproducenten de gemiddelde variabele kosten kunnen dalen dankzij een importverbod.$$, 'inline'),
  ('de77de61-486a-4e76-b2db-3aec6dd400a0', 'dab62abd-af81-4541-b98b-0f905c8c92dc', $$geloofwaardigheid van een tijdelijk importverbod$$,
   $$economie-vwo-2018-i-zakelijk-boeren-context7.png$$,
   $$Voor het slagen van dit protectionistische beleid moet het voor de marktpartijen voldoende geloofwaardig zijn dat de overheid na een bepaalde periode een einde zal maken aan het importverbod.$$, 'inline'),
  ('8491ddb2-fcac-475d-b440-b88a6c52e4c3', 'c0096151-61e9-4957-a14c-1d6429af4732', $$beleidsregel CB: Rb = Ia + 2 + 0,5(Ia − Id) met legenda$$,
   $$economie-vwo-2018-i-monetair-beleid-goed-geregeld-context1.png$$,
   $$De centrale bank (CB) van een land streeft er naar om door beïnvloeding van de rente de stijging van het algemene prijspeil op jaarbasis op 2% te houden. Elke maand stelt de CB de rente vast, waarbij zij uitgaat van de meest recente inflatiecijfers. De beleidsrente bepaalt zij op basis van het verschil tussen de actuele inflatie en de inflatiedoelstelling:
Rb = Ia + 2 + 0,5(Ia − Id)
De symbolen hebben de volgende betekenis (in procenten):
Rb = de nominale beleidsrente
Ia = actuele inflatie
Id = inflatiedoelstelling$$, 'inline'),
  ('83aabe9c-d86c-4f7e-ad49-58ac7b26807e', 'c0096151-61e9-4957-a14c-1d6429af4732', $$bij lichte deflatie negatieve nominale rente maar positieve reële rente$$,
   $$economie-vwo-2018-i-monetair-beleid-goed-geregeld-context2.png$$,
   $$Met het hanteren van deze regel zal volgens de CB bij een lichte deflatie weliswaar gekozen worden voor een negatieve nominale rente, maar zal de reële rente positief kunnen blijven.$$, 'inline'),
  ('b9ab68d6-fe7a-4dc8-9bb4-08704d88b4bd', 'c0096151-61e9-4957-a14c-1d6429af4732', $$vraaguitval door dalende export: inflatie daalt van 2% naar 1%$$,
   $$economie-vwo-2018-i-monetair-beleid-goed-geregeld-context3.png$$,
   $$De toepassing van de beleidsregel heeft volgens de CB in de afgelopen periode geleid tot een redelijk stabiel prijspeil. De laatste tijd is er echter sprake van een forse vraaguitval doordat de export afneemt. De CB wil vasthouden aan de bovenstaande beleidsregel. Stel dat door de vraaguitval de actuele inflatie op jaarbasis daalt van 2% naar 1%.$$, 'inline'),
  ('7f0fae8c-4b2c-4117-8aba-70f53c469ead', 'c0096151-61e9-4957-a14c-1d6429af4732', $$uitgebreide beleidsregel met werkloosheid: + ß(Ua − Un)$$,
   $$economie-vwo-2018-i-monetair-beleid-goed-geregeld-context4.png$$,
   $$Een econoom meent dat naast de inflatie ook de omvang van de werkloosheid dient te worden meegewogen bij de bepaling van de beleidsrente. Als de actuele werkloosheid wordt gerelateerd aan de werkloosheid die op lange termijn als inflatieneutraal geldt, levert dit de volgende uitgebreide beleidsregel:
Rb = Ia + 2 + 0,5(Ia − Id) + ß(Ua − Un)
Ua = het actuele werkloosheidspercentage
Un = Non Accelerating Inflation Rate of Unemployment (NAIRU)$$, 'inline'),
  ('f2b29ca2-dd33-467d-8aff-3940632edaed', 'c0096151-61e9-4957-a14c-1d6429af4732', $$NAIRU 4%; nominale rente niet onder nul; inflatie 1%, ß = −0,3$$,
   $$economie-vwo-2018-i-monetair-beleid-goed-geregeld-context5.png$$,
   $$De NAIRU wordt geschat op 4% van de beroepsbevolking. De president van de CB vindt de nieuwe beleidsregel een goede suggestie, maar als zekerheid voor het behoud van de stabiliteit van het bankwezen wil hij de nominale rente niet onder nul laten dalen. Volgens hem kan zich een situatie voordoen met lage inflatie en hoge werkloosheid waarbij de CB de nieuwe regel dan niet meer kan hanteren. Hij gaat uit van een actuele inflatie van 1% en een ß van −0,3.$$, 'inline'),
  ('1350fb4b-9fa1-45f1-9b1f-3d956a2a8890', 'c0096151-61e9-4957-a14c-1d6429af4732', $$waarschuwing: gevolgen als de CB de beleidsregel moet loslaten$$,
   $$economie-vwo-2018-i-monetair-beleid-goed-geregeld-context6.png$$,
   $$De president van de CB waarschuwt voor de gevolgen als de CB na invoering van de beleidsregel deze noodgedwongen toch moet loslaten. Dit zou ertoe kunnen leiden dat in de toekomst de inflatie minder stabiel zal zijn.$$, 'inline'),
  ('4330b1cc-1fd5-4f2d-86ff-8fde46690f69', '808be5b8-d76b-452f-80b0-9cda91a3ea42', $$inleiding: economisch herstel, dalend overheidstekort en groot uitvoersaldo van Nederland$$,
   $$economie-vwo-2018-i-hun-probleem-ons-probleem-context1.png$$,
   $$Met een voorzichtig economisch herstel in de eurozone veerde ook de Nederlandse economie eind 2014 weer op: het reëel bruto binnenlands product (bbp) groeide, het overheidstekort daalde en het positieve uitvoersaldo met de rest van de eurozone werd groter. Enkele eurolanden waar de groei achterbleef, vonden dat Nederland en andere Noord- Europese landen ruimte hadden om hun bestedingen te stimuleren, zodat in de Zuid-Europese landen het handelstekort kon verminderen. De Nederlandse overheid wilde het eigen tekort en daarmee de overheidsschuld echter niet laten stijgen, vooral met het oog op het rentetarief op staatsobligaties. Het Nederlandse uitvoersaldo (uitvoer minus invoer) als percentage van het bbp was inmiddels hoger geworden dan het door de Europese Commissie aangegeven maximum van 6%.$$, 'inline'),
  ('09857f22-974b-410d-88c4-62fbcbf9978e', '808be5b8-d76b-452f-80b0-9cda91a3ea42', $$raming CPB: herstel zet door in 2015$$,
   $$economie-vwo-2018-i-hun-probleem-ons-probleem-context2.png$$,
   $$Volgens een raming van het Centraal Planbureau (CPB) in 2014 zou het economisch herstel in Nederland in 2015 doorzetten. Het CPB publiceerde voor Nederland de volgende gegevens:$$, 'inline'),
  ('b96a9007-6cf2-4cb6-9311-10b2a4ab6598', '808be5b8-d76b-452f-80b0-9cda91a3ea42', $$tabel 1: macro-economische gegevens CPB voor Nederland (2014, 2015)$$,
   $$economie-vwo-2018-i-hun-probleem-ons-probleem-context3.png$$,
   $$Tabel 1 macro-economische gegevens CPB voor Nederland
| 2014 | 2015
particuliere consumptie | € 292,4 mld. | € 298,9 mld.
particuliere bruto-investeringen | € 96,7 mld. | € 101,5 mld.
bruto-overheidsbestedingen | € 194,8 mld. | € 194,1 mld.
uitvoer | € 544,5 mld. | …………
invoer | € 474,3 mld. | € 491,1 mld.
nominaal bbp | € 654,1 mld. | € 667,7 mld.
overheidstekort als % van het bbp* | 2,8 | 1,8
* einde van het jaar$$, 'inline'),
  ('176f9ba9-9f3b-4447-8ea9-ae3ce7f63c48', '808be5b8-d76b-452f-80b0-9cda91a3ea42', $$econoom: daling tekortpercentage door toename particuliere investeringen$$,
   $$economie-vwo-2018-i-hun-probleem-ons-probleem-context4.png$$,
   $$Een econoom stelt dat de verwachte daling van het overheidstekort als percentage van het bbp mede wordt veroorzaakt door de verwachte toename van de particuliere bruto-investeringen.$$, 'inline'),
  ('95090985-4d4f-4252-a178-6b2dcd971896', '808be5b8-d76b-452f-80b0-9cda91a3ea42', $$uitvoersaldo 2014 bedroeg 10,73% van het bbp$$,
   $$economie-vwo-2018-i-hun-probleem-ons-probleem-context5.png$$,
   $$Met behulp van tabel 1 kan berekend worden dat het positieve uitvoersaldo van Nederland over 2014 10,73% van het bbp bedroeg.$$, 'inline'),
  ('c3f27c1f-7918-4251-b9ef-4f29b5631db2', '808be5b8-d76b-452f-80b0-9cda91a3ea42', $$stimuleringsbeleid in Nederland helpt Zuid-Europa$$,
   $$economie-vwo-2018-i-hun-probleem-ons-probleem-context6.png$$,
   $$Sommige economen zien in het groeiende uitvoersaldo en het lage overheidstekort van Nederland ruimte voor een stimuleringsbeleid. Dat zou Zuid-Europese landen helpen bij hun economisch herstel, wat op zijn beurt ook de continuïteit van de groei in Nederland zou kunnen bevorderen.$$, 'inline'),
  ('a1da2393-5299-4c8d-9066-f3777b6fba84', 'd9acf0b9-f661-49c8-9fa8-5ce9c95f7b95', $$inleiding: middeninkomens profiteren weinig van woonbeleid$$,
   $$economie-vwo-2018-i-middeninkomens-trekken-aan-het-kortste-eind-context1.png$$,
   $$Uit een onderzoek blijkt dat het beleid met betrekking tot het huren van woningen in verhouding weinig voordeel biedt aan mensen met middeninkomens. Zij hebben relatief weinig profijt van huurtoeslagen, die immers voornamelijk worden verstrekt aan huurders met lage inkomens. Ook profiteren mensen met middeninkomens in verhouding weinig van overheidsbeleid dat is gericht op de markt van koopwoningen.$$, 'inline'),
  ('1ac99eb7-c179-4d01-a823-6458fe857951', 'd9acf0b9-f661-49c8-9fa8-5ce9c95f7b95', $$model huurwoningmarkt met en zonder huurtoeslag (Qᵥᵗ, Qᵥ, Qₐ) en legenda$$,
   $$economie-vwo-2018-i-middeninkomens-trekken-aan-het-kortste-eind-context2.png$$,
   $$De onderzoeker analyseert allereerst de huurwoningmarkt, geldend voor mensen met de laagste inkomens. Hij gaat uit van standaardwoningen, waarbij elke huurder eenzelfde bedrag aan huurtoeslag ontvangt. Daarvoor hanteert hij een model met een vraag- en een aanbodfunctie.
Qᵥᵗ = −0,5P + 8
Qₐ = P − 2
Zonder huurtoeslag zou de vraagfunctie de volgende gedaante hebben:
Qᵥ = −0,5P + 7
Qᵥᵗ = vraag naar huurwoningen met huurtoeslag (× 100.000)
Qᵥ = vraag naar huurwoningen zonder huurtoeslag (× 100.000)
Qₐ = aanbod van huurwoningen (× 100.000)
P = huur per maand (× € 100)$$, 'inline'),
  ('27d90620-6721-4231-8328-c5b7658637e9', 'd9acf0b9-f661-49c8-9fa8-5ce9c95f7b95', $$huurtoeslag verandert betalingsbereidheid en leidt tot inkomensstijging verhuurders$$,
   $$economie-vwo-2018-i-middeninkomens-trekken-aan-het-kortste-eind-context3.png$$,
   $$Het verstrekken van huurtoeslag beïnvloedt volgens het onderzoek de marktuitkomsten op de markt van huurwoningen. Door huurtoeslag verandert namelijk de betalingsbereidheid van huurders. Daarbij blijkt de huurtoeslag onbedoeld te leiden tot inkomensstijging van verhuurders.$$, 'inline'),
  ('4f78642e-3b08-4b28-af32-37a663748c35', 'd9acf0b9-f661-49c8-9fa8-5ce9c95f7b95', $$fiscale aftrek hypotheekrente komt vooral ten goede aan hoogste inkomens$$,
   $$economie-vwo-2018-i-middeninkomens-trekken-aan-het-kortste-eind-context4.png$$,
   $$Een ander onderdeel van het woonbeleid, de fiscale aftrek van de hypotheekrente, komt voornamelijk ten goede aan mensen met de hoogste inkomens. Deze wonen namelijk vaak in relatief dure koopwoningen, en bovendien werkt het progressieve stelsel van inkomstenbelasting in hun voordeel.$$, 'inline'),
  ('7f5a50a7-a9df-41da-92b2-9069792ffee7', 'd9acf0b9-f661-49c8-9fa8-5ce9c95f7b95', $$voorstel: drie maatregelen tegen denivellerende hypotheekrenteaftrek$$,
   $$economie-vwo-2018-i-middeninkomens-trekken-aan-het-kortste-eind-context5.png$$,
   $$De onderzoeker stelt dat aan het ongewenste prijseffect van de huurtoeslag weinig is te doen. Hij betoogt dat er wel mogelijkheden zijn om de denivellerende effecten van de hypotheekrenteaftrek tegen te gaan en stelt een combinatie van drie maatregelen voor, waarbij de ontvangsten van de overheid per saldo niet zullen worden aangetast:
− verlaging van de maximale belastingteruggave over de hypotheekrente van 50% (het tarief van de hoogste inkomensschijf) naar 40%;
− beperking van de fiscale aftrek van hypotheekrente tot een maximale hypotheekschuld van € 400.000 (bij een hogere schuld wordt voor de aftrek uitgegaan van € 400.000);
− verlaging van het marginale belastingtarief voor de middelste inkomensschijf van 42% naar 40%.$$, 'inline'),
  ('f9ffc814-ec1e-47b4-ada6-103727830039', '516f99fc-c03a-45f3-ad8f-585be7a977e2', $$inleiding: keuze tussen bedrag ineens en maandelijkse pensioenuitkeringen$$,
   $$economie-vwo-2018-i-pensioen-inpakken-en-wegwezen-context1.png$$,
   $$Tot nu toe worden aanvullende pensioenen in Nederland uitsluitend uitgekeerd als een bedrag per maand. Uit onderzoek blijkt echter dat veel pensioengerechtigden de voorkeur hebben om een deel van dit pensioen als een bedrag ineens te ontvangen, dat wordt uitgekeerd op de datum van pensionering. Econoom Theuns, werkzaam bij een pensioenfonds, geeft een overzicht welke keuze dit fonds dan aan pensioengerechtigden kan bieden. Hij gaat ervan uit dat pensioendeelnemers vanaf de leeftijd van 67 jaar recht hebben op pensioen. Hoe groter het deel van de pensioenpot is dat wordt ingezet voor een bedrag ineens, des te lager is het resterende deel van de pensioenpot dat wordt ingezet voor maandelijkse uitkeringen. Figuur 1 geeft de mogelijke combinaties van uitkeringen weer.$$, 'inline'),
  ('e09e1ac3-0a2e-4857-9f8b-afe046423e12', '516f99fc-c03a-45f3-ad8f-585be7a977e2', $$figuur 1: combinaties van keuzemogelijkheden voor pensioen; deelnemer met € 200.000 pensioenwaarde$$,
   $$economie-vwo-2018-i-pensioen-inpakken-en-wegwezen-context2.png$$,
   $$Figuur 1 combinaties van keuzemogelijkheden voor pensioen
Grafiek: dalende rechte lijn van 100% bedrag ineens (bij 0% maandelijkse uitkering) naar 0% bedrag ineens bij 0,60% maandelijkse uitkering. Verticale as: bedrag ineens in % van de pensioenwaarde (0-100); horizontale as: maandelijkse uitkering in % van de pensioenwaarde (0-0,60).
Een pensioendeelnemer heeft bij pensionering een verwachte pensioenwaarde van € 200.000, en wil hiervan maandelijks minstens € 480 aan pensioenuitkering ontvangen.$$, 'inline'),
  ('4912820a-3b0a-480a-aad5-8593a1e93b66', '516f99fc-c03a-45f3-ad8f-585be7a977e2', $$Theuns: verwacht beleggingsrendement daalt, maandelijkse uitkering kan worden verlaagd$$,
   $$economie-vwo-2018-i-pensioen-inpakken-en-wegwezen-context3.png$$,
   $$Er zijn omstandigheden die pensioenfondsen ertoe kunnen aanzetten om de percentages voor de maandelijkse pensioenuitkeringen in de loop der tijd bij te stellen. Theuns voorziet dat het verwachte beleggingsrendement waarop figuur 1 is gebaseerd, zal dalen. Met het oog daarop waarschuwt hij de pensioendeelnemer dat in de loop der jaren zijn maandelijkse bedrag kan worden verlaagd.$$, 'inline'),
  ('0055c304-5708-4b0d-9d64-4c27a52a587d', '516f99fc-c03a-45f3-ad8f-585be7a977e2', $$collega: mensen met korte levensverwachting kiezen eerder voor bedrag ineens$$,
   $$economie-vwo-2018-i-pensioen-inpakken-en-wegwezen-context4.png$$,
   $$Een collega merkt op dat pensioengerechtigden bij de keuze tussen een bedrag ineens en maandelijkse uitkeringen hun tijdsvoorkeur en ook hun levensverwachting zullen betrekken. De kans bestaat dat mensen met een (op medische indicatie gebaseerde) korte levensverwachting eerder zullen kiezen om hun hele pensioendeel alvast in één keer te laten uitbetalen.$$, 'inline'),
  ('eb04124e-2e46-4c70-b408-83ea6e2b2bdd', '516f99fc-c03a-45f3-ad8f-585be7a977e2', $$Theuns presenteert onderzoek naar levensverwachting$$,
   $$economie-vwo-2018-i-pensioen-inpakken-en-wegwezen-context5.png$$,
   $$In tabel 1 presenteert Theuns uitkomsten van een onderzoek naar de levensverwachting van pensioengerechtigden.$$, 'inline'),
  ('da158e76-5645-442b-8229-36a44e52cee2', '516f99fc-c03a-45f3-ad8f-585be7a977e2', $$tabel 1: inschatting van de levensverwachting bij 65-jarigen$$,
   $$economie-vwo-2018-i-pensioen-inpakken-en-wegwezen-context6.png$$,
   $$Tabel 1 inschatting van de levensverwachting bij 65-jarigen
geslacht | percentage dat 75 jaar of ouder wordt: door personen zelf geschat i. | demografisch bepaald ii.
man | 63% | 82%
vrouw | 69% | 90%
i. percentage van de geïnterviewde personen dat verwacht een leeftijd te bereiken van 75 jaar of hoger
ii. percentage op basis van demografisch onderzoek$$, 'inline'),
  ('5837fd9d-566f-4c54-b5c1-cb1018b60ae1', '516f99fc-c03a-45f3-ad8f-585be7a977e2', $$conclusie: keuzevrijheid en onjuiste inschatting levensverwachting$$,
   $$economie-vwo-2018-i-pensioen-inpakken-en-wegwezen-context7.png$$,
   $$Theuns concludeert dat keuzevrijheid, samen met een onjuiste inschatting van de eigen levensverwachting, voor veel pensioengerechtigden ertoe kan leiden dat ze op enig moment in de toekomst hun gewenste levensstandaard niet meer kunnen behouden.$$, 'inline'),
  ('bfa5bb25-7eb5-4ff3-80c7-073667025bbf', 'e5eb041b-5957-471a-b999-478948c8b07d', $$inleiding: hoge overheidsuitgaven, verslechterde concurrentiepositie, neerwaartse loonstarheid$$,
   $$economie-vwo-2018-i-overheid-in-de-greep-van-markten-context1.png$$,
   $$In een land zijn de uitgaven van de overheid jarenlang sterk gegroeid. De belastingen zijn hoog in verhouding tot het gemiddelde inkomen per hoofd van de bevolking en de loonkosten per product zijn over het algemeen hoog. De internationale concurrentiepositie van het land is verslechterd. De groei van het bruto binnenlands product (bbp) is de laatste jaren achtergebleven bij die van de belangrijkste buitenlandse handelspartners. Ondertussen is het overheidstekort flink opgelopen. Op de valutamarkt, de vermogensmarkt en de goederenmarkt zijn zowel binnenlandse als buitenlandse vragers en aanbieders actief. Op de arbeidsmarkt zijn alleen binnenlandse vragers en aanbieders actief. Hier is sprake van neerwaartse loonstarheid waardoor werkloosheid kan ontstaan. Met het oog op de geschetste problemen verricht een commissie van het ministerie van Economische Zaken onderzoek naar het overheidssaldo en de werkloosheid. De commissie stelt dat de effectiviteit van overheidsbeleid afhankelijk is van ontwikkelingen op de vermogensmarkt, de valutamarkt, de goederenmarkt en de arbeidsmarkt.$$, 'inline'),
  ('87854394-317b-4899-a3c0-e0cee7ad3bad', 'e5eb041b-5957-471a-b999-478948c8b07d', $$beleggers kunnen vertrouwen in staatsobligaties verliezen$$,
   $$economie-vwo-2018-i-overheid-in-de-greep-van-markten-context2.png$$,
   $$De commissie constateert dat beleggers door ontwikkelingen op de valutamarkt hun vertrouwen kunnen verliezen om in staatsobligaties van dit land (uitgedrukt in de nationale valuta) te beleggen.$$, 'inline'),
  ('a95fdd63-7ee8-4c60-82c0-881cef394be8', 'e5eb041b-5957-471a-b999-478948c8b07d', $$politicus: extra overheidsbestedingen tegen werkloosheid; kritiek commissie$$,
   $$economie-vwo-2018-i-overheid-in-de-greep-van-markten-context3.png$$,
   $$Een politicus pleit voor extra overheidsbestedingen op de goederenmarkt om de werkloosheid te bestrijden. De commissie heeft als kritiek dat dit plan zou kunnen leiden tot een verder oplopend overheidstekort, als gevolg waarvan de werkloosheid zelfs zou kunnen toenemen.$$, 'inline');

insert into practice_questions (id, exercise_id, question_number, topics, keywords, question_summary, question_image_url, question_text, context_block_ids) values
  ('9cfcf28b-7a61-48dc-849f-bda8fcd4c98b', 'dab62abd-af81-4541-b98b-0f905c8c92dc', 1,
   '[{"domain": "Markt", "subdomain": "Doelmatigheid en economische politiek"}]'::jsonb,
   '["consumentensurplus", "producentensurplus", "totaal surplus", "wereldmarktprijs", "import"]'::jsonb,
   $$Aanwijzen van het totale surplus in een marktgrafiek met import tegen de wereldmarktprijs.$$,
   $$economie-vwo-2018-i-zakelijk-boeren-vraag1.png$$, $$1p 1 Noem de letters van de vlakken in figuur 1 waarmee het totale gerealiseerde surplus wordt weergegeven, voordat het importverbod wordt ingesteld.$$, array['312cf323-d798-4754-b4d0-7aa30134553e', 'ecf140c3-48b1-4867-a107-f33dd4056e5a', '7a23cae2-3f29-41f5-9159-f96eceaca203', 'd2a1ba47-3b9a-43f9-acf2-e2f9dc2eae74']::uuid[]),
  ('0005a0a7-0d98-41df-b2c6-aab11f974e75', 'dab62abd-af81-4541-b98b-0f905c8c92dc', 2,
   '[{"domain": "Markt", "subdomain": "Doelmatigheid en economische politiek"}]'::jsonb,
   '["welvaartsverlies", "importverbod", "Harberger-driehoek", "totaal surplus", "protectionisme"]'::jsonb,
   $$Aanwijzen van het welvaartsverlies door een importverbod in een marktgrafiek.$$,
   $$economie-vwo-2018-i-zakelijk-boeren-vraag2.png$$, $$1p 2 Noem de letter(s) van het vlak / de vlakken waarmee het welvaartsverlies in dit land wordt weergegeven dat ontstaat door de instelling van het importverbod.$$, array['312cf323-d798-4754-b4d0-7aa30134553e', 'ecf140c3-48b1-4867-a107-f33dd4056e5a', '7a23cae2-3f29-41f5-9159-f96eceaca203', 'd2a1ba47-3b9a-43f9-acf2-e2f9dc2eae74']::uuid[]),
  ('8aa6f085-df29-4e0e-a6ee-2a73a320f5c8', 'dab62abd-af81-4541-b98b-0f905c8c92dc', 3,
   '[{"domain": "Markt", "subdomain": "Vraag en aanbod"}, {"domain": "Markt", "subdomain": "Doelmatigheid en economische politiek"}]'::jsonb,
   '["importquotum", "marktevenwicht", "vraagvergelijking", "aanbodvergelijking", "prijsstijging berekenen"]'::jsonb,
   $$Berekenen van de toegestane importhoeveelheid waarbij de binnenlandse prijs 10% stijgt.$$,
   $$economie-vwo-2018-i-zakelijk-boeren-vraag3.png$$, $$2p 3 Bereken bij welke hoogte van de toegestane hoeveelheid import de prijsstijging 10% bedraagt.$$, array['ecf140c3-48b1-4867-a107-f33dd4056e5a', 'b9a10ae9-93db-41f6-92ee-718579f6f341']::uuid[]),
  ('3eec5af4-494d-4988-b142-77e5ead35a7d', 'dab62abd-af81-4541-b98b-0f905c8c92dc', 4,
   '[{"domain": "Markt", "subdomain": "Vraag en aanbod"}]'::jsonb,
   '["variabele kosten", "verschuiving aanbodlijn", "wereldmarktprijs", "aanbodvergelijking", "kostendaling berekenen"]'::jsonb,
   $$Berekenen van de kostendaling waarbij binnenlands aanbod de vraag bij de wereldmarktprijs dekt.$$,
   $$economie-vwo-2018-i-zakelijk-boeren-vraag4.png$$, $$2p 4 Bereken met welk bedrag de variabele kosten per ton moeten dalen om ervoor te zorgen dat er geen import meer plaatsvindt als het importverbod later wordt afgeschaft.$$, array['ecf140c3-48b1-4867-a107-f33dd4056e5a', '7a23cae2-3f29-41f5-9159-f96eceaca203', 'a684ec44-57ef-4198-9d95-f2addf640b60']::uuid[]),
  ('0133743c-057e-441e-b062-87adecb42152', 'dab62abd-af81-4541-b98b-0f905c8c92dc', 5,
   '[{"domain": "Markt", "subdomain": "Vraag en aanbod"}]'::jsonb,
   '["gemiddelde vaste kosten", "schaalvoordelen", "productieomvang", "importverbod"]'::jsonb,
   $$Verklaren waarom de gemiddelde vaste kosten dalen als de binnenlandse productie toeneemt.$$,
   $$economie-vwo-2018-i-zakelijk-boeren-vraag5.png$$, $$1p 5 Verklaar dat ook de gemiddelde vaste kosten kunnen dalen als gevolg van het importverbod.$$, array['a684ec44-57ef-4198-9d95-f2addf640b60']::uuid[]),
  ('fe5b753f-f7fd-42ac-b360-864bae73fb2d', 'dab62abd-af81-4541-b98b-0f905c8c92dc', 6,
   '[{"domain": "Samenwerken en onderhandelen", "subdomain": "Speltheorie"}]'::jsonb,
   '["geloofwaardigheid", "zelfbinding", "protectionisme", "prikkels", "efficiëntie"]'::jsonb,
   $$Uitleggen waarom een tijdelijk importverbod alleen werkt als de beëindiging geloofwaardig is.$$,
   $$economie-vwo-2018-i-zakelijk-boeren-vraag6.png$$, $$1p 6 Leg dit uit.$$, array['de77de61-486a-4e76-b2db-3aec6dd400a0']::uuid[]),
  ('5545fa07-1682-4045-94ce-059a7cc6ae3c', 'c0096151-61e9-4957-a14c-1d6429af4732', 7,
   '[{"domain": "Goede tijden, slechte tijden", "subdomain": "Monetair beleid en de centrale bank"}, {"domain": "Goede tijden, slechte tijden", "subdomain": "Conjunctuur"}]'::jsonb,
   '["reële rente", "nominale rente", "deflatie", "beleidsregel", "reële rente berekenen"]'::jsonb,
   $$Berekenen bij welke deflatie de reële rente volgens een rentebeleidsregel nul wordt.$$,
   $$economie-vwo-2018-i-monetair-beleid-goed-geregeld-vraag7.png$$, $$2p 7 Bereken bij welke actuele deflatie de reële rente gezakt zou zijn tot een waarde van nul, uitgaande van de inflatiedoelstelling.$$, array['8491ddb2-fcac-475d-b440-b88a6c52e4c3', '83aabe9c-d86c-4f7e-ad49-58ac7b26807e']::uuid[]),
  ('1ad25376-368d-449d-b115-783e6bbe9c9e', 'c0096151-61e9-4957-a14c-1d6429af4732', 8,
   '[{"domain": "Goede tijden, slechte tijden", "subdomain": "Monetair beleid en de centrale bank"}]'::jsonb,
   '["negatieve rente", "bankrun", "spaargeld", "rentemarge", "banken"]'::jsonb,
   $$Verklaren waarom een negatieve nominale rente banken in problemen kan brengen.$$,
   $$economie-vwo-2018-i-monetair-beleid-goed-geregeld-vraag8.png$$, $$1p 8 Verklaar waarom banken in problemen kunnen komen als de nominale rente negatief zou worden.$$, array['83aabe9c-d86c-4f7e-ad49-58ac7b26807e']::uuid[]),
  ('9c8d38b2-a75a-4016-b0e8-c6db0b5817c4', 'c0096151-61e9-4957-a14c-1d6429af4732', 9,
   '[{"domain": "Goede tijden, slechte tijden", "subdomain": "Monetair beleid en de centrale bank"}, {"domain": "Goede tijden, slechte tijden", "subdomain": "Conjunctuur"}]'::jsonb,
   '["rentebeleid", "beleidsrente", "bestedingen", "inflatie", "vraaguitval"]'::jsonb,
   $$Uitleggen hoe een renteverlaging volgens de beleidsregel de inflatie weer laat stijgen.$$,
   $$economie-vwo-2018-i-monetair-beleid-goed-geregeld-vraag9.png$$, $$2p 9 Leg zonder berekening uit dat de toepassing van de beleidsregel ertoe kan leiden dat de inflatie dan weer toeneemt.$$, array['8491ddb2-fcac-475d-b440-b88a6c52e4c3', 'b9ab68d6-fe7a-4dc8-9bb4-08704d88b4bd']::uuid[]),
  ('5d88127f-d044-4035-8c85-bb75945589e9', 'c0096151-61e9-4957-a14c-1d6429af4732', 10,
   '[{"domain": "Goede tijden, slechte tijden", "subdomain": "Monetair beleid en de centrale bank"}]'::jsonb,
   '["duaal mandaat", "beleidsregel", "werkloosheid", "NAIRU", "anticyclisch rentebeleid"]'::jsonb,
   $$Uitleggen waarom de werkloosheidscoëfficiënt in een rentebeleidsregel negatief moet zijn.$$,
   $$economie-vwo-2018-i-monetair-beleid-goed-geregeld-vraag10.png$$, $$2p 10 Leg uit dat aan de coëfficiënt ß een negatieve waarde moet worden toegekend.$$, array['7f0fae8c-4b2c-4117-8aba-70f53c469ead']::uuid[]),
  ('f418961e-766c-442a-b7c4-237ead5b8ec6', 'c0096151-61e9-4957-a14c-1d6429af4732', 11,
   '[{"domain": "Goede tijden, slechte tijden", "subdomain": "Monetair beleid en de centrale bank"}]'::jsonb,
   '["effectieve ondergrens nominale rente", "zero lower bound", "beleidsregel", "NAIRU", "werkloosheid berekenen"]'::jsonb,
   $$Berekenen bij welke werkloosheid de beleidsrente volgens de regel de nulondergrens bereikt.$$,
   $$economie-vwo-2018-i-monetair-beleid-goed-geregeld-vraag11.png$$, $$2p 11 Bereken bij welke omvang van de actuele werkloosheid de CB te maken krijgt met de nulondergrens (zero lower bound) van de nominale rente.$$, array['8491ddb2-fcac-475d-b440-b88a6c52e4c3', '7f0fae8c-4b2c-4117-8aba-70f53c469ead', 'f2b29ca2-dd33-467d-8aff-3940632edaed']::uuid[]),
  ('adbded6b-3154-49bd-a10a-e26adbd251bc', 'c0096151-61e9-4957-a14c-1d6429af4732', 12,
   '[{"domain": "Goede tijden, slechte tijden", "subdomain": "Monetair beleid en de centrale bank"}, {"domain": "Goede tijden, slechte tijden", "subdomain": "Conjunctuur"}]'::jsonb,
   '["geloofwaardigheid", "inflatieverwachtingen", "loononderhandelingen", "loon-prijsspiraal", "beleidsregel"]'::jsonb,
   $$Uitleggen waarom consequent volgen van een rentebeleidsregel via inflatieverwachtingen het prijspeil stabiliseert.$$,
   $$economie-vwo-2018-i-monetair-beleid-goed-geregeld-vraag12.png$$, $$3p 12 Leg uit dat het consequent hanteren van de regel voor het rentebeleid essentieel is voor het behoud van een stabiel prijspeil. Gebruik de volgende aspecten:
− de geloofwaardigheid van het monetaire beleid bij het publiek
− de inflatieverwachtingen van het publiek wanneer de beleidsregel wordt toegepast en de effecten daarvan op de uitkomst van de loononderhandelingen$$, array['1350fb4b-9fa1-45f1-9b1f-3d956a2a8890']::uuid[]),
  ('80a55878-05c2-4d67-88b4-d78eb0ed5640', '808be5b8-d76b-452f-80b0-9cda91a3ea42', 13,
   '[{"domain": "Ruilen over de tijd", "subdomain": "Intertemporele ruil"}]'::jsonb,
   '["staatsschuld", "overheidstekort", "wanbetalingsrisico", "rente op staatsobligaties", "risicopremie"]'::jsonb,
   $$Verklaren waarom een dalend overheidstekort de rente op staatsleningen verlaagt.$$,
   $$economie-vwo-2018-i-hun-probleem-ons-probleem-vraag13.png$$, $$2p 13 Verklaar dat de Nederlandse overheid door het dalende overheidstekort tegen een lager rentetarief zou kunnen lenen.$$, array['4330b1cc-1fd5-4f2d-86ff-8fde46690f69']::uuid[]),
  ('11945f32-ab32-40e5-9dc7-e63f7e1c2e2e', '808be5b8-d76b-452f-80b0-9cda91a3ea42', 14,
   '[{"domain": "Goede tijden, slechte tijden", "subdomain": "Begrotingsbeleid"}, {"domain": "Welvaart en groei", "subdomain": "Macro-economische kringloop"}]'::jsonb,
   '["tekortpercentage", "particuliere investeringen", "belastingontvangsten", "bbp", "automatische stabilisatoren"]'::jsonb,
   $$Verklaren hoe hogere investeringen via teller en noemer het tekort als percentage van het bbp verlagen.$$,
   $$economie-vwo-2018-i-hun-probleem-ons-probleem-vraag14.png$$, $$2p 14 Verklaar deze stelling. Betrek in je verklaring zowel de teller als de noemer van de berekening van het tekortpercentage.$$, array['09857f22-974b-410d-88c4-62fbcbf9978e', 'b96a9007-6cf2-4cb6-9311-10b2a4ab6598', '176f9ba9-9f3b-4447-8ea9-ae3ce7f63c48']::uuid[]),
  ('30cfc33c-2ad5-4f51-bf5f-8d3d6c5c6d26', '808be5b8-d76b-452f-80b0-9cda91a3ea42', 15,
   '[{"domain": "Welvaart en groei", "subdomain": "Macro-economische kringloop"}]'::jsonb,
   '["uitvoersaldo", "bestedingsmethode", "Y = C + I + O + E − M", "percentage van het bbp berekenen"]'::jsonb,
   $$Berekenen van het uitvoersaldo als percentage van het bbp met de bestedingsvergelijking.$$,
   $$economie-vwo-2018-i-hun-probleem-ons-probleem-vraag15.png$$, $$2p 15 Toon met een berekening aan dat volgens de ramingen het uitvoersaldo van Nederland als percentage van het bbp in 2015 hoger is dan in 2014.$$, array['09857f22-974b-410d-88c4-62fbcbf9978e', 'b96a9007-6cf2-4cb6-9311-10b2a4ab6598', '95090985-4d4f-4252-a178-6b2dcd971896']::uuid[]),
  ('f6133eb3-a9ff-402b-b151-83625df9d662', '808be5b8-d76b-452f-80b0-9cda91a3ea42', 16,
   '[{"domain": "Welvaart en groei", "subdomain": "Macro-economische kringloop"}, {"domain": "Goede tijden, slechte tijden", "subdomain": "Conjunctuur"}]'::jsonb,
   '["internationale handel", "uitvoer", "invoer", "multiplier", "bestedingen"]'::jsonb,
   $$Verklaren hoe meer productie in andere landen via hun invoer tot meer Nederlandse uitvoer leidt.$$,
   $$economie-vwo-2018-i-hun-probleem-ons-probleem-vraag16.png$$, $$2p 16 Verklaar dat een toename van de productie in de Zuid-Europese landen uiteindelijk ook kan leiden tot een toename van de Nederlandse uitvoer.$$, array['c3f27c1f-7918-4251-b9ef-4f29b5631db2']::uuid[]),
  ('51f21e4d-7f8a-4b6f-8de4-8a614351ff6e', 'd9acf0b9-f661-49c8-9fa8-5ce9c95f7b95', 17,
   '[{"domain": "Markt", "subdomain": "Vraag en aanbod"}]'::jsonb,
   '["verschuiving vraaglijn", "huurtoeslag", "betalingsbereidheid", "vraagvergelijking", "subsidie berekenen"]'::jsonb,
   $$Berekenen van de huurtoeslag uit de verticale verschuiving van de vraaglijn.$$,
   $$economie-vwo-2018-i-middeninkomens-trekken-aan-het-kortste-eind-vraag17.png$$, $$1p 17 Laat met een berekening zien dat de huurtoeslag per standaardhuurwoning € 200 per maand bedraagt.$$, array['a1da2393-5299-4c8d-9066-f3777b6fba84', '1ac99eb7-c179-4d01-a823-6458fe857951']::uuid[]),
  ('ed92984f-6af0-418b-b697-6431b62e02ff', 'd9acf0b9-f661-49c8-9fa8-5ce9c95f7b95', 18,
   '[{"domain": "Markt", "subdomain": "Doelmatigheid en economische politiek"}, {"domain": "Markt", "subdomain": "Vraag en aanbod"}]'::jsonb,
   '["subsidie", "marktevenwicht", "evenwichtsprijs", "verdeling van surplus", "procentuele verdeling berekenen"]'::jsonb,
   $$Berekenen welk deel van een subsidie aan vragers via een hogere prijs bij aanbieders terechtkomt.$$,
   $$economie-vwo-2018-i-middeninkomens-trekken-aan-het-kortste-eind-vraag18.png$$, $$2p 18 Bereken hoeveel procent van de huurtoeslag per woning ten goede komt aan de verhuurders.$$, array['1ac99eb7-c179-4d01-a823-6458fe857951', '27d90620-6721-4231-8328-c5b7658637e9']::uuid[]),
  ('f3424962-93d6-43ab-939c-126849cb908a', 'd9acf0b9-f661-49c8-9fa8-5ce9c95f7b95', 19,
   '[{"domain": "Welvaart en groei", "subdomain": "Ongelijkheid en herverdeling"}]'::jsonb,
   '["hypotheekrenteaftrek", "progressief belastingstelsel", "marginaal tarief", "denivelleren", "aftrekpost"]'::jsonb,
   $$Uitleggen waarom hoge inkomens via duurdere woningen en hogere marginale tarieven het meest profiteren van hypotheekrenteaftrek.$$,
   $$economie-vwo-2018-i-middeninkomens-trekken-aan-het-kortste-eind-vraag19.png$$, $$2p 19 Leg uit dat door elk van beide genoemde factoren, mensen met de hoogste inkomens het meest profiteren van de fiscale aftrek van hypotheekrente.$$, array['4f78642e-3b08-4b28-af32-37a663748c35']::uuid[]),
  ('dbcc6612-1630-4ff1-9031-0eaa991208eb', 'd9acf0b9-f661-49c8-9fa8-5ce9c95f7b95', 20,
   '[{"domain": "Welvaart en groei", "subdomain": "Ongelijkheid en herverdeling"}]'::jsonb,
   '["nivelleren", "marginaal tarief", "hypotheekrenteaftrek", "inkomensschijf", "belastingmaatregelen"]'::jsonb,
   $$Verklaren hoe een combinatie van belastingmaatregelen nivellerend werkt tussen hoge en middeninkomens.$$,
   $$economie-vwo-2018-i-middeninkomens-trekken-aan-het-kortste-eind-vraag20.png$$, $$2p 20 Verklaar dat dit voorstel een nivellerend effect kan hebben tussen de hoogste inkomens en de middeninkomens. Betrek alle drie onderdelen van het voorstel in je antwoord.$$, array['7f5a50a7-a9df-41da-92b2-9069792ffee7']::uuid[]),
  ('fe9164ac-7ced-479f-b787-28925ee8974d', 'd9acf0b9-f661-49c8-9fa8-5ce9c95f7b95', 21,
   '[{"domain": "Welvaart en groei", "subdomain": "Ongelijkheid en herverdeling"}]'::jsonb,
   '["belastingontvangsten", "hypotheekrenteaftrek", "budgetneutraal", "tariefverlaging", "aftrekbeperking"]'::jsonb,
   $$Verklaren waarom een pakket belastingmaatregelen budgetneutraal kan zijn.$$,
   $$economie-vwo-2018-i-middeninkomens-trekken-aan-het-kortste-eind-vraag21.png$$, $$2p 21 Verklaar dat deze combinatie van maatregelen kan worden ingevoerd zonder dat de ontvangsten van de overheid per saldo hoeven terug te lopen.$$, array['7f5a50a7-a9df-41da-92b2-9069792ffee7']::uuid[]),
  ('cb2d63b6-a961-41af-b67f-11e8c4dca3ad', '516f99fc-c03a-45f3-ad8f-585be7a977e2', 22,
   '[{"domain": "Ruilen over de tijd", "subdomain": "Registratie intertemporele ruil"}]'::jsonb,
   '["pensioen", "bedrag ineens berekenen", "maandelijkse uitkering", "pensioenwaarde", "grafiek aflezen"]'::jsonb,
   $$Berekenen van het maximale bedrag ineens bij een minimale maandelijkse pensioenuitkering.$$,
   $$economie-vwo-2018-i-pensioen-inpakken-en-wegwezen-vraag22.png$$, $$2p 22 Bereken aan de hand van figuur 1 het bedrag dat deze deelnemer dan maximaal ineens kan ontvangen bij het bereiken van de pensioenleeftijd.$$, array['f9ffc814-ec1e-47b4-ada6-103727830039', 'e09e1ac3-0a2e-4857-9f8b-afe046423e12']::uuid[]),
  ('b657bbf9-f31d-47dd-b40d-aa05c0e57559', '516f99fc-c03a-45f3-ad8f-585be7a977e2', 23,
   '[{"domain": "Ruilen over de tijd", "subdomain": "Intertemporele ruil"}, {"domain": "Ruilen over de tijd", "subdomain": "Registratie intertemporele ruil"}]'::jsonb,
   '["ruilen over de tijd", "pensioenopbouw", "uitgestelde consumptie", "sparen", "levensloop"]'::jsonb,
   $$Verklaren waarom pensioenopbouw een vorm van ruilen over de tijd is.$$,
